-- Source-pinned T_CORE_FILE in-place restoration; no business rows or attachment bytes.
-- Oracle DDL implicitly commits. Failure can leave partial DDL; preserve the execution log.
-- Require application verification/jobs quiescent before execution. No atomic rollback claim.
WHENEVER SQLERROR EXIT FAILURE ROLLBACK
WHENEVER OSERROR EXIT FAILURE ROLLBACK
SET DEFINE OFF
SET SQLBLANKLINES ON
SET SERVEROUTPUT ON
DECLARE
  n PLS_INTEGER;
  column_count PLS_INTEGER;
  v_semantics VARCHAR2(10);
  PROCEDURE verify_structure(restored BOOLEAN) IS
  BEGIN
    IF restored THEN
    SELECT COUNT(*) INTO n FROM ALL_TABLES WHERE OWNER='LIMS_RUNTIME_LOCAL' AND TABLE_NAME='T_CORE_FILE' AND TEMPORARY='N' AND NESTED='NO' AND SECONDARY='N' AND PARTITIONED='NO';
    IF n<>1 THEN RAISE_APPLICATION_ERROR(-20002, 'Incompatible ALL_TABLES'); END IF;
    SELECT COUNT(*) INTO n FROM ALL_TAB_COLS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND TABLE_NAME='T_CORE_FILE';
