  IF n<>0 THEN RAISE_APPLICATION_ERROR(-20001,'Nonempty T_CORE_FILE'); END IF;
  SELECT COUNT(*) INTO column_count FROM ALL_TAB_COLS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND TABLE_NAME='T_CORE_FILE';
